import { observer } from 'mobx-react-lite';
import React, { useEffect, useState } from 'react';
import {  useParams} from 'react-router-dom/cjs/react-router-dom';
import { useContext } from 'react';
import { Context } from '../index';
import { Badge, Button, Card, Col, Container, Dropdown, Row, Spinner } from 'react-bootstrap'
import { getOneOrder, getOneOrderInfo } from '../http/orderAPI';

const OrderPage = observer(() => {
  const {order} = useContext(Context)
  const {user} = useContext(Context)
  const id = useParams()
  const [loading, setLoading] = useState(true)

  function stop(){
    setLoading(false)
  }

  useEffect(() =>{
    getOneOrderInfo(id.id).then(oneOrder => {
      order.setOneOrder(oneOrder.order);
      order.setDishes(oneOrder.orderInfo);
    }).finally(setTimeout(stop, 1000))
  }, [])

  if (loading){
    return <Spinner animation={"grow"}/>
  }

  function color(status){
    switch(status){
      case 'Нове':
        return 'primary'
      case 'Відхилено':
        return 'danger'
      case 'Прийняте':
        return 'info'
      case 'Готується':
        return 'warning'
      case 'В доставці':
        return 'secondary'
      case 'Виконано':
        return 'success'
    }
  }

  return (
    <Container className="min-vh-100 d-flex flex-sm-column mt-3">
      {user.user.role === 'ADMIN' ? 
          <Dropdown>
            
          </Dropdown>
      :
        <h3>Замовлення №{id.id} <Badge bg={color(order.oneOrder.status)}>{order.oneOrder.status}</Badge></h3>
      }
      <div>Ім'я: {order.oneOrder.name}</div>
      <div>Телефон: {order.oneOrder.phone}</div>
      <div>Адреса доставки: {order.oneOrder.address}</div>
      <div>Тип оплати: {order.oneOrder.paytype}</div>
      <hr/>
      <div><b>Склад замовлення:</b></div>

      {order.dishes.map(product =>
        <Card className="d-flex p-2 justify-content-center mb-2" key={product.id}>
        <Row className="d-flex w-100">
          <Col>
            <div className="d-flex flex-row align-items-center">
              <img className='rounded-2' src={process.env.REACT_APP_API_URL + product.dish.img} width={50} />
              <h4 className="pl-3">{product.dish.name}</h4>
            </div>
          </Col>
          <Col>
            <div className="d-flex h-100 flex-row justify-content-end align-items-center">
              <h3 className="font-weight-light">{product.dish.price} грн</h3>
            </div>
          </Col>
        </Row>
      </Card>
      )}
    </Container>
  );
});

export default OrderPage;
